    ]),
    unitList() {
      return this.findAllUnit
    },

    dialogMessage() {
      return this.message !== null
    },

    // Tax rate options for autocomplete
    taxRateOptions() {
      return this.taxRates.map((rate) => ({
        id: rate.id,
        name: rate.name,
        code: rate.code,
        rate: rate.rate,
        isDefault: rate.isDefault,
        displayText: `${rate.name} (${rate.code})`,
        displayRate: `${(rate.rate * 100).toFixed(1)}%`,
