            }
          </style>
              </head>
              <body>
                  <div style="text-align: center;">
                        <table style="width: 200px; text-align: center;" >
                            <tr>
                              <td style="width: 500px; height: 15px;font-size:8px;">
                                ລາຄາ:${this.formatNumber(
                                  this.formData.pro_price
                                )}
